import fs from 'node:fs';
const html = fs.readFileSync('/app/index.html','utf8');
const m = html.match(/<script>([\s\S]*?)<\/script>/);
if(!m) throw new Error('no inline script');
const script = m[1];
if(/https?:\/\/|<link|<img|src\s*=/.test(html.replace(/url\(#/g,''))) throw new Error('external asset found');

let rafCb=null, rafCount=0;
const grad={addColorStop(){}};
const ctx={ setTransform(){}, clearRect(){}, createRadialGradient(){return grad}, beginPath(){}, arc(){}, fill(){},
  set fillStyle(v){}, get fillStyle(){return ''}, set globalCompositeOperation(v){}, get globalCompositeOperation(){return ''} };
const canvas={ width:0,height:0, style:{}, getContext:()=>ctx };
const styleProps={};
const bodyEl={ style:{ setProperty(k,v){ styleProps[k]=v; } } };
const listeners={};
global.window={
  innerWidth:1200, innerHeight:800, devicePixelRatio:1,
  addEventListener:(t,f)=>{listeners[t]=f},
  matchMedia:(q)=>({matches:false, addEventListener(){}}),
  requestAnimationFrame:(cb)=>{rafCb=cb; return ++rafCount},
};
global.document={ getElementById:(id)=> id==='fx'?canvas : id==='scene'?{} : {style:{}} , body:bodyEl };
global.requestAnimationFrame=global.window.requestAnimationFrame;
global.cancelAnimationFrame=()=>{};

eval(script);
// run several RAF frames (fallback must invoke queued callback)
for(let i=0;i<12;i++){ const cb=rafCb; rafCb=null; if(!cb) throw new Error('no RAF queued at frame '+i); cb(); }
// simulate pointer move
if(listeners['pointermove']) listeners['pointermove']({clientX:1000, clientY:200});
for(let i=0;i<6;i++){ const cb=rafCb; rafCb=null; cb(); }
console.log('SMOKE_OK frames=18 mx=',styleProps['--mx'],'lx=',styleProps['--lx'],'canvas=',canvas.width+'x'+canvas.height);
// reduced-motion path
let mqHandler=null;
global.window.matchMedia=(q)=>({matches:true, addEventListener:(t,f)=>{mqHandler=f}});
eval(script);
console.log('REDUCED_OK handler=', typeof mqHandler);
